code_sketch.helper_home_streak:
def _home_streak(self, team, team_home_results):
    games = team_home_results.get(team, [])
    if not games: return 0
    result = 1 if games[-1][1] else -1
    for g in reversed(games[:-1]):
        if (1 if g[1] else -1) == result: result += (1 if games[-1][1] else -1)
        else: break
    return result

